// #endregion 🔌️Adapters

//#region 🔖️TextEditorHost
//#region Types
type GrammarToken = { readonly class: string; readonly start: number; readonly end: number };

type EditorDiagnostic = { readonly start: number; readonly end: number; readonly severity?: string; readonly message: string };

type FrameworkEditorSession = EditorWasmSession;

type SpanRange = { readonly start: number; readonly end: number };

type CompletionItem = { readonly label: string; readonly detail?: string; readonly insertText?: string };

type RenameInfo = { readonly name: string; readonly occurrences: readonly SpanRange[] };

type RenameDraft = { readonly occurrences: readonly SpanRange[]; readonly text: string };

type PickTarget = { readonly domain: string; readonly id: string; readonly generality?: number; readonly label: string };

export type TextEditorExplicitDraftSettings = Readonly<{
  readOnly: false;
  editAction: string;
  editArgument: string;
  editArguments: Readonly<Record<string, unknown>>;
  commit: "explicit";
  applyLabel: string;
  discardLabel: string;
  conflictLabel: string;
  applyingLabel: string;
  cancelLabel: string;
  failedLabel: string;
}>;

export type TextEditorExplicitDraftState = Readonly<{ surfaceId: string; base: string; draft: string; dirty: boolean; conflicted: boolean }>;
//#endregion Types

const TOKEN_CLASS_COLORS: Record<string, string> = {
  keyword: "text-info",
  string: "text-success",
  number: "text-warning",
  operator: "text-primary",
  ident: "text-foreground",
};

//#region HighlightedBuffer
function HighlightedBuffer({ buffer, tokens }: { readonly buffer: string; readonly tokens: readonly GrammarToken[] }) {
  if (tokens.length === 0) {
    return <span className="whitespace-pre-wrap font-mono text-xs text-foreground">{buffer}</span>;
  }
  const parts: ReactNode[] = [];
  let cursor = 0;
  for (const token of tokens) {
    if (token.start > cursor) parts.push(<span key={`plain-${cursor}`}>{buffer.slice(cursor, token.start)}</span>);
    const color = TOKEN_CLASS_COLORS[token.class] ?? "text-foreground";
    parts.push(
      <span key={`token-${token.start}-${token.end}`} className={`font-mono text-xs ${color}`}>
        {buffer.slice(token.start, token.end)}
      </span>,
    );
    cursor = Math.max(cursor, token.end);
  }
  if (cursor < buffer.length) parts.push(<span key={`tail-${cursor}`}>{buffer.slice(cursor)}</span>);
  return <div className="pointer-events-none absolute inset-0 overflow-hidden whitespace-pre-wrap p-3">{parts}</div>;
}
//#endregion HighlightedBuffer

//#region EditingHelpers
/** 🌐️ Resolves a translation key outside of component render (e.g. text-editor context menu helpers) — an alias of {@link shellLabel} scoped to this region.
 * Exported (unlike the rest of this helper set) — a still-barrel-resident block-builder region references it unqualified. */
export function hostLabel(key: UiTranslationKey): string {
  return shellLabel(key);
}

/** ✂️ Language-agnostic multi-span rename preview: replaces every span with `nextName`, remapping spans left-to-right. */
export function multiSpanReplace(text: string, occurrences: readonly SpanRange[], nextName: string): { readonly text: string; readonly occurrences: readonly SpanRange[] } {
  const sorted = [...occurrences].sort((a, b) => b.start - a.start);
  let out = text;
  const nextOccurrences: SpanRange[] = [];
  for (const occ of sorted) {
    out = `${out.slice(0, occ.start)}${nextName}${out.slice(occ.end)}`;
    nextOccurrences.unshift({ start: occ.start, end: occ.start + nextName.length });
  }
  return { text: out, occurrences: nextOccurrences };
}

export function lineRangeAt(text: string, offset: number): SpanRange {
  const start = text.lastIndexOf("\n", Math.max(0, offset - 1)) + 1;
  const nextNewline = text.indexOf("\n", offset);
  const end = nextNewline === -1 ? text.length : nextNewline;
  return { start, end };
}

function identifierPrefixStart(text: string, caret: number): number {
  let start = caret;
  while (start > 0 && /[A-Za-z0-9_]/.test(text[start - 1] ?? "")) start -= 1;
  return start;
}

/** 🔁️ What one editor host knows about its own edits in flight: the texts it sent and has not seen echoed yet (oldest
 * first) and the last text an echo acknowledged. */
export type TextEditorEchoStateV1 = { readonly pending: readonly string[]; readonly acknowledged: string | null };

/** 🔁️ The host's optimistic local echo (fixture `🧫️fixtures/🔁️local-echo/🔣️.json`). While this editor types, its OWN text and
 * caret are the newest state: a scene that only echoes what the host delivered — a buffer equal to a pending sent text (it
 * acknowledges that text and every older one) or to the last acknowledged text (the guest re-publishing a state it already
 * echoed, e.g. when a job finishes) — applies neither its buffer nor its selection, because both lag the editor (ticket
 * 26/09/23 F1: an older echo reverted typing still in flight, and an echoed selection threw the caret back mid-word, which
 * scrambled a fast run). Any other buffer is an external change (undo, a collaborator, a formatter): the host applies its
 * text and selection at once and drops every pending send. */
export function reconcileTextEditorEchoV1(state: TextEditorEchoStateV1, buffer: string): TextEditorEchoStateV1 & { readonly external: boolean } {
  const index = state.pending.indexOf(buffer);
  if (index >= 0) return { external: false, pending: state.pending.slice(index + 1), acknowledged: buffer };
  if (buffer === state.acknowledged) return { external: false, pending: state.pending, acknowledged: state.acknowledged };
  return { external: true, pending: [], acknowledged: buffer };
}

/** 🕳️ The hidden textarea is the editor's INPUT SINK (focus, IME, clipboard): the wasm session owns the text and the
 * caret, so the textarea's own value changes are never an edit — typing, compositions, pastes and text inserted without a
 * key of its own (a dead key, the emoji picker, dictation: `beforeinput` `insertText`) arrive as key, composition,
 * clipboard and input events and are applied at the session's caret. */
function ignoreInputSinkChange(): void {}

export const TEXT_EDITOR_CARET_BLINK_MS = 500;

export type TextEditorCaretCadenceV1 = Readonly<{
  reset: () => void;
  suspend: () => void;
  dispose: () => void;
  visible: () => boolean;
  armed: () => boolean;
}>;

/** ⌨️ Gives the canvas editor the focus-owned caret cadence native HTML inputs receive from
 * the browser. The hidden textarea remains the focus/IME authority; the canvas session receives
 * only visible-state transitions and paints the caret itself. */
export function installTextEditorCaretCadenceV1(target: HTMLTextAreaElement, present: (visible: boolean) => void): TextEditorCaretCadenceV1 {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let current = false;
  let focused = target.ownerDocument.activeElement === target;
  const publish = (visible: boolean) => {
    if (current === visible) return;
    current = visible;
    present(visible);
  };
  const clear = () => {
    if (timer !== undefined) clearTimeout(timer);
    timer = undefined;
  };
  const arm = () => {
    clear();
    if (!focused) return;
    timer = setTimeout(() => {
      timer = undefined;
      if (!focused) return;
      publish(!current);
      arm();
    }, TEXT_EDITOR_CARET_BLINK_MS);
  };
  const reset = () => {
    if (!focused) return;
    publish(true);
    arm();
  };
  const focus = () => {
    focused = true;
    reset();
  };
  const suspend = () => {
    focused = false;
    clear();
    publish(false);
  };
  const resetEvents = ["beforeinput", "input", "keydown", "pointerdown", "compositionstart", "compositionupdate", "compositionend"] as const;
  target.addEventListener("focus", focus);
  target.addEventListener("blur", suspend);
  for (const event of resetEvents) target.addEventListener(event, reset);
  target.ownerDocument.defaultView?.addEventListener("pagehide", suspend);
  if (focused) reset();
  else present(false);
  return {
    reset,
    suspend,
    visible: () => current,
    armed: () => timer !== undefined,
    dispose: () => {
      suspend();
      target.removeEventListener("focus", focus);
      target.removeEventListener("blur", suspend);
      for (const event of resetEvents) target.removeEventListener(event, reset);
      target.ownerDocument.defaultView?.removeEventListener("pagehide", suspend);
    },
  };
}

/** 🚫️ A refused edit never reaches the guest: it leaves the pending set, and once nothing is pending any more the host
 * re-applies the guest's own buffer (`resync`) — the typed text the guest did not take disappears together with the
 * shell's refusal notice instead of lingering as an edit that looks saved (ticket 26/09/23 F1: every keystroke after the
 * 64th of the trinity query was refused while the editor kept showing it). */
export function refuseTextEditorEditV1(state: TextEditorEchoStateV1, text: string): TextEditorEchoStateV1 & { readonly resync: boolean } {
  const index = state.pending.indexOf(text);
  if (index < 0) return { ...state, resync: false };
  const pending = [...state.pending.slice(0, index), ...state.pending.slice(index + 1)];
  return { pending, acknowledged: state.acknowledged, resync: pending.length === 0 };
}

/** 🧾️ The refusal reason of a dispatch outcome (the input ledger's `applied | refused | superseded`), or `null` when the
 * input was not refused. */
/** ✅️ Whether a dispatched action's typed outcome says the guest APPLIED it — its typed operation completed. */
function outcomeApplied(outcome: unknown): boolean {
  return typeof outcome === "object" && outcome !== null && (outcome as { readonly kind?: unknown }).kind === "applied";
}

function refusalReason(outcome: unknown): string | null {
  if (typeof outcome !== "object" || outcome === null) return null;
  const answer = outcome as { readonly kind?: unknown; readonly reason?: unknown };
  return answer.kind === "refused" ? String(answer.reason ?? "") : null;
}

/** 🔒️ Refusals that mean the window takes no text edits at all — a derived view (a compiled DSL, a script projection)
 * declares no `textEdit`, a viewer is read-only: the editor turns read-only instead of refusing every further keystroke
 * (ticket 26/09/23 F1: typing 158 keys into the dag/flow/sequence compiled windows raised 300 refusals). */
export const TEXT_EDITOR_READ_ONLY_REFUSALS: ReadonlySet<string> = new Set(["undeclared-action", "viewer-read-only"]);

/** ✍️ Whether a key edits the text (so a read-only editor swallows it): a printable key, Enter, Tab, Backspace, Delete. */
function isTextEditingKey(event: { readonly key: string; readonly metaKey: boolean; readonly ctrlKey: boolean; readonly altKey: boolean }): boolean {
  if (event.key === "Enter" || event.key === "Tab" || event.key === "Backspace" || event.key === "Delete") return !event.metaKey && !event.ctrlKey;
  return event.key.length === 1 && !event.metaKey && !event.ctrlKey && !event.altKey;
}

/** ⏪️ The document history verb a key chord asks for inside the editor (`mod+z` undo, `mod+shift+z` / `ctrl+y` redo). The
 * shell's own chords stand down while a text field has focus — right for a native field, which undoes itself — but the
 * editor's input sink is not a field of its own: its text lives in the document, so its undo is the document's
 * (ticket 26/09/23 F1: Cmd+Z in the writer and query editors did nothing). */
export function documentHistoryChord(event: { readonly key: string; readonly metaKey: boolean; readonly ctrlKey: boolean; readonly shiftKey: boolean; readonly altKey: boolean }): "undo" | "redo" | null {
  if (event.altKey || !(event.metaKey || event.ctrlKey)) return null;
  const key = event.key.toLowerCase();
  if (key === "z") return event.shiftKey ? "redo" : "undo";
  if (key === "y" && event.ctrlKey && !event.metaKey) return "redo";
  return null;
}

/** 📮️ What the editor owes the guest: its latest text and selection (byte offsets of the session). */
type TextEditorOutboxV1 = { readonly text: string; readonly start: number; readonly end: number };

/** 📮️ The editor's outbox: at most ONE round trip in flight, and each delivery carries the editor's state AS IT IS WHEN THE
 * DELIVERY GOES OUT (`read`), never a snapshot taken when it was owed — a scene that folded a collaborator's run into the editor
 * in between is part of what goes out (ticket 26/09/23 C12, live wave p33: a splice computed from a snapshot older than that fold
 * deleted the collaborator's run and re-inserted everything around it, so both editors duplicated and lost runs). `notify` after
 * every change; a state equal to the last one delivered is not sent again; a refused round trip frees the lane like a settled one.
 * @see ../🧫️fixtures/📮️delivery/🔣️.json */
export function createTextEditorOutboxV1<T>(read: () => T | null, deliver: (value: T) => unknown, isEqual: (a: T, b: T) => boolean): () => void {
  let inFlight = false;
  let owed = false;
  let lastSent: T | undefined;
  const flush = () => {
    if (inFlight || !owed) return;
    owed = false;
    const next = read();
    if (next === null || (lastSent !== undefined && isEqual(lastSent, next))) return;
    lastSent = next;
    inFlight = true;
    const release = () => {
      inFlight = false;
      flush();
    };
    void Promise.resolve(deliver(next)).then(release, release);
  };
  return () => {
    owed = true;
    flush();
  };
}

/** 🧮️ Most edits one editor keeps in flight before an echo acknowledges them. */
const TEXT_EDITOR_PENDING_EDIT_LIMIT = 256;

/** 🪞️ The scene fields an echo of the editor's own state carries back — its text and its selection. */
const TEXT_EDITOR_ECHOED_FIELDS: ReadonlySet<string> = new Set(["buffer", "selectionJson"]);

/** 🧾️ Whether a paged-carrier lane transports an echoed field: its ref (`bytes` + `hash` of the buffer) changes with
 * every keystroke, so an echo that kept it would re-sync — and repaint — an unchanged editor once per key. Read at call time:
 * the lane table is imported through a module cycle and is not initialised while this module evaluates. */
function textEditorEchoedLaneV1(lane: string): boolean {
  return TEXT_EDITOR_SCENE_LANES.some((entry) => entry.lane === lane && TEXT_EDITOR_ECHOED_FIELDS.has(entry.field));
}

/** ✂️ A scene without what an echo of the editor's own state must not apply — its buffer, its selection and the
 * lane refs that describe the buffer; every other field (tokens, diagnostics, completions…) stays and syncs. */
export function sceneWithoutEchoedTextV1(scene: TextEditorScene): Record<string, unknown> {
  const lanes = scene.lanes?.filter((ref) => !textEditorEchoedLaneV1(ref.lane));
  return Object.fromEntries(Object.entries(scene).flatMap(([key, value]): [string, unknown][] => (TEXT_EDITOR_ECHOED_FIELDS.has(key) ? [] : key === "lanes" ? (lanes?.length ? [[key, lanes]] : []) : [[key, value]])));
}

/** 📦️ The pack the editor syncs for `scene`: the whole scene when it is external (another author's text), else the
 * scene without the echo of its own state (ticket 26/09/23 F3: the buffer's lane ref made every echo re-sync). */
export function textEditorSyncPackV1(scene: TextEditorScene, external: boolean): Uint8Array {
  return new Uint8Array(encodePackValue(external ? scene : sceneWithoutEchoedTextV1(scene)));
}

/** 🟰️ Whether two encoded scene packs carry the same bytes. */
export function sameScenePackV1(left: Uint8Array, right: Uint8Array): boolean {
  if (left.length !== right.length) return false;
  for (let index = 0; index < left.length; index++) if (left[index] !== right[index]) return false;
  return true;
}

function parseJsonOr<T>(json: string | undefined, fallback: T): T {
  if (!json) return fallback;
  try {
    return parseSceneJsonField<T>(json);
  } catch {
    return fallback;
  }
}

/** 📝 Decodes the strict explicit-commit subset of a text-editor scene's settings. */
export function parseTextEditorExplicitDraftSettings(json: string | undefined): TextEditorExplicitDraftSettings | null {
  if (!json) return null;
  try {
    const value = JSON.parse(json) as Record<string, unknown>;
    if (
      value === null ||
      Array.isArray(value) ||
      value.readOnly !== false ||
      value.commit !== "explicit" ||
      typeof value.editAction !== "string" ||
      value.editAction.length === 0 ||
      typeof value.editArgument !== "string" ||
      value.editArgument.length === 0 ||
      typeof value.applyLabel !== "string" ||
      value.applyLabel.length === 0 ||
      typeof value.discardLabel !== "string" ||
      value.discardLabel.length === 0 ||
      typeof value.conflictLabel !== "string" ||
      value.conflictLabel.length === 0 ||
      typeof value.applyingLabel !== "string" ||
      value.applyingLabel.length === 0 ||
      typeof value.cancelLabel !== "string" ||
      value.cancelLabel.length === 0 ||
      typeof value.failedLabel !== "string" ||
      value.failedLabel.length === 0 ||
      (value.editArguments !== undefined && (value.editArguments === null || typeof value.editArguments !== "object" || Array.isArray(value.editArguments)))
    ) return null;
    return {
      readOnly: false,
      editAction: value.editAction,
      editArgument: value.editArgument,
      editArguments: (value.editArguments ?? {}) as Readonly<Record<string, unknown>>,
      commit: "explicit",
      applyLabel: value.applyLabel,
      discardLabel: value.discardLabel,
      conflictLabel: value.conflictLabel,
      applyingLabel: value.applyingLabel,
      cancelLabel: value.cancelLabel,
      failedLabel: value.failedLabel,
    };
  } catch {
    return null;
  }
}

/** 📦 Merges a local draft into its artifact-owned action without mutating static arguments. */
export function textEditorExplicitDraftAction(settings: TextEditorExplicitDraftSettings, draft: string): ActionDescriptor {
  return { controllerId: "", action: settings.editAction, args: { ...settings.editArguments, [settings.editArgument]: draft } };
}

/** 🔄 Preserves dirty local text across rerenders and accepts only its exact persisted echo. */
export function reconcileTextEditorExplicitDraft(state: TextEditorExplicitDraftState, surfaceId: string, sceneBuffer: string): TextEditorExplicitDraftState {
  if (state.surfaceId !== surfaceId || !state.dirty || state.draft === sceneBuffer) return { surfaceId, base: sceneBuffer, draft: sceneBuffer, dirty: false, conflicted: false };
  return { ...state, conflicted: sceneBuffer !== state.base };
}

/** ✍️ Recomputes dirty/conflict state against the latest persisted buffer for each local edit. */
export function changeTextEditorExplicitDraft(state: TextEditorExplicitDraftState, surfaceId: string, sceneBuffer: string, draft: string): TextEditorExplicitDraftState {
  if (state.surfaceId !== surfaceId || draft === sceneBuffer) return { surfaceId, base: sceneBuffer, draft, dirty: draft !== sceneBuffer, conflicted: false };
  return { surfaceId, base: state.base, draft, dirty: true, conflicted: sceneBuffer !== state.base };
}

//#endregion EditingHelpers

/** 🔢️ A wasm editor session's selection in scalars of `text` (the session speaks UTF-8 bytes); the text's end without one. */
function textEditorSessionSelectionV1(session: FrameworkEditorSession | null, text: string): { readonly anchor: number; readonly caret: number } {
  const end = Array.from(text).length;
  return session === null ? { anchor: end, caret: end } : { anchor: scalarOfUtf8OffsetV1(text, session.anchor()), caret: scalarOfUtf8OffsetV1(text, session.caret()) };
}

/** 🖼️ Shows what splice typing answered (ticket 26/09/23 C12, `semio.ui.scene.text-splice.v1`): the text, then the selection in
 * the session's UTF-8 bytes; nothing for `null` (the editor already shows it). */
function showTextEditorSpliceViewV1(session: FrameworkEditorSession | null, view: TextEditorSpliceViewV1): void {
  if (session === null || view === null) return;
  session.setText(view.text);
  session.setSelectionRange(utf8OffsetOfScalarV1(view.text, view.anchor), utf8OffsetOfScalarV1(view.text, view.caret));
}

//#region WasmEditorSurface
/** 🖋️ The canvas text editor. It never paints on its own: the session {@link GraphWasmCanvas} hands it is the
 * frame-demanding handle, where every call invalidates and the canvas paints once at the next frame. Its handlers used to
 * call `renderFrame` (a synchronous paint) after every change on top of that, and every echo of its own edit was synced
 * again even when its pack was byte-identical to the one already applied (the selection round trip), so one keystroke
 * painted 3.7–4.1 times — writer 4.13, trinity jack 3.67 per key, measured by the latency gate's paint hook (ticket
 * 26/09/23 F2). A scene pack is now synced once per session.
 *
 * @see 🧰️framework/🛍️products/💻️os/🔨️modules/🧑‍💻dev/🧪️tests/⏱️interaction-latency/🟦️.ts */
function WasmEditorSurface({
  scene,
  controllerId,
  surfaceId,
  onAction,
  explicitDraft,
  explicitDraftDirty,
  onDraftChange,
  requestContextMenu,
}: {
  readonly scene: TextEditorScene;
  readonly controllerId: string;
  readonly surfaceId: string;
  readonly onAction: (action: ActionDescriptor) => void;
  readonly explicitDraft?: TextEditorExplicitDraftSettings | null;
  readonly explicitDraftDirty?: boolean;
  readonly onDraftChange?: (text: string) => void;
  readonly requestContextMenu?: (request: PluginContextMenuRequest) => Promise<readonly ContextMenuItemSpec[]>;
}) {
  const sessionRef = useRef<FrameworkEditorSession | null>(null);
  const renameActiveRef = useRef(false);
  const lastHoverRangeRef = useRef<SpanRange | null>(null);
  const echoStateRef = useRef<TextEditorEchoStateV1>({ pending: [], acknowledged: null });
  const reconciledRef = useRef<{ readonly scene: TextEditorScene; readonly pack: Uint8Array } | null>(null);
  const syncedRef = useRef<{ readonly session: FrameworkEditorSession; readonly pack: Uint8Array } | null>(null);
  const explicitHistoryRef = useRef<{ past: string[]; current: string; future: string[] }>({ past: [], current: scene.buffer, future: [] });

  useEffect(() => {
    if (!explicitDraft || explicitDraftDirty === false || explicitHistoryRef.current.current !== scene.buffer) {
      explicitHistoryRef.current = { past: [], current: scene.buffer, future: [] };
    }
  }, [explicitDraft, explicitDraftDirty, scene.buffer]);

  const dispatch = useCallback(
    (action: string, args?: Record<string, unknown>) => {
      onAction({ controllerId, action, args: { surfaceId, ...args } });
    },
    [controllerId, onAction, surfaceId],
  );
  const textEditorMenuKeysByActionId = useAppKeybindingsByActionId();
  const shellContextMenuFallback = useShellContextMenuFallback();

  const syncSessionRef = useRef<(resync?: boolean) => void>(() => {});
  const readOnlyRef = useRef(false);
  const [readOnly, setReadOnly] = useState(false);
  const selectionUndeclaredRef = useRef(false);
  const spliceHostRef = useRef<TextEditorSpliceHostV1 | null>(null);
  const spliceTyping = useMemo(() => textEditorTypingV1(scene.settingsJson) !== null, [scene.settingsJson]);
  const spliceTypingRef = useRef(false);
  spliceTypingRef.current = spliceTyping && !explicitDraft;
  /** 📮️ ONE round trip in flight per editor, latest state wins: a typed run is delivered as the editor's text and selection AT
   * DELIVERY (`createTextEditorOutboxV1`) whenever the previous delivery settled, never one `textEdit` + one `textSelect` per key —
   * sustained typing at 40 keys/s filled the per-actor command queue (`queue-full`, > 256 pending turns) and dropped keys
   * (ticket 26/09/23 F1). The texts that do go out are the ones the echo reconciliation waits for. The dispatcher lives as long
   * as the surface and reads its owner through `deliveryOwnerRef`: a dispatcher rebuilt on every new `onAction` identity left
   * the previous one flushing its own stale pending text AFTER the newer one had gone out, so the guest took an older buffer
   * last and the author's final keys vanished (ticket 26/09/23 C11, probe `c11typing3`). */
  const deliveryOwnerRef = useRef({ controllerId, explicitDraft, onAction, onDraftChange, surfaceId });
  deliveryOwnerRef.current = { controllerId, explicitDraft, onAction, onDraftChange, surfaceId };
  /** ⌨️ Publishes the editor's pending run as the ephemeral shared preview peers render at its caret (`null` once it ended). */
  const publishTypingPreview = (surfaceId: string, local: string) => {
    const preview = typingRef.current?.preview(local) ?? null;
    publishLocalPresenceTypingV1("local", surfaceId || "text", preview === null ? null : { deleted: preview.deleted, insert: preview.insert });
  };
  /** ⌨️ The editor's live typing run (design §13.2 of ticket 26/09/30/NON-DESTRUCTIVE-HISTORY-EDITING): every delivery the
   * window took names this editor's buffer (`typing`), so the window folds it into ONE run that commits as ONE document edit; the
   * host ends the run on idle, a caret move, blur and a hidden page — never one edit per keystroke, never a coalesce key. */
  const typingRef = useRef<TextEditorTypingRunV1 | null>(null);
  typingRef.current ??= createTextEditorTypingRunV1(
    (verb, reason) => {
      const { controllerId, onAction, surfaceId } = deliveryOwnerRef.current;
      publishLocalPresenceTypingV1("local", surfaceId || "text", null);
      void onAction({ controllerId, action: verb, args: { surfaceId, [TEXT_EDITOR_TYPING_BUFFER_ARG]: surfaceId, [TEXT_EDITOR_TYPING_COMMIT_ARG]: reason } });
    },
    (run, ms) => {
      const timer = setTimeout(run, ms);
      return () => clearTimeout(timer);
    },
  );
  const deliver = useMemo(
    () =>
      createTextEditorOutboxV1<TextEditorOutboxV1>(
        () => {
          const session = sessionRef.current;
          return session === null ? null : { text: session.text(), start: session.anchor(), end: session.caret() };
        },
        async (next) => {
          const { controllerId, explicitDraft, onAction, onDraftChange, surfaceId } = deliveryOwnerRef.current;
          if (explicitDraft) {
            const history = explicitHistoryRef.current;
            if (history.current !== next.text) explicitHistoryRef.current = { past: [...history.past, history.current].slice(-256), current: next.text, future: [] };
            echoStateRef.current = { pending: [], acknowledged: next.text };
            onDraftChange?.(next.text);
            return;
          }
          const spliceHost = spliceHostRef.current;
          if (spliceTypingRef.current && spliceHost !== null) {
            const sent = readOnlyRef.current ? null : sendTextEditorSpliceV1(spliceHost, next.text);
            if (sent !== null) {
              spliceHostRef.current = sent.host;
              const outcome = await onAction({ controllerId, action: textEditorActions.splice, args: { surfaceId, ...sent.splice, seq: sent.seq, anchor: next.start, caret: next.end, [TEXT_EDITOR_TYPING_BUFFER_ARG]: surfaceId } });
              const reason = refusalReason(outcome);
              if (reason === null) {
                if (outcomeApplied(outcome)) spliceHostRef.current = settleTextEditorSpliceV1(spliceHostRef.current ?? sent.host, sent.seq);
                typingRef.current?.typed(textEditorActions.splice, spliceHost.base);
                publishTypingPreview(surfaceId, next.text);
                return;
              }
              if (TEXT_EDITOR_READ_ONLY_REFUSALS.has(reason)) {
                readOnlyRef.current = true;
                setReadOnly(true);
              }
              const session = sessionRef.current;
              const local = session?.text() ?? next.text;
              const refused = refuseTextEditorSpliceV1(spliceHostRef.current ?? sent.host, sent.seq, local, textEditorSessionSelectionV1(session, local));
              spliceHostRef.current = refused.host;
              showTextEditorSpliceViewV1(session, refused.show);
              return;
            }
            typingRef.current?.commit(TEXT_EDITOR_TYPING_HOST_SIGNALS.caretMove);
            if (selectionUndeclaredRef.current) return;
            const reason = refusalReason(await onAction({ controllerId, action: textEditorActions.select, args: { surfaceId, start: next.start, end: next.end, splice: spliceHost.seq } }));
            if (reason === "undeclared-action") selectionUndeclaredRef.current = true;
            return;
          }
          const echo = echoStateRef.current;
          const guestHasText = echo.pending.length > 0 ? echo.pending.at(-1) === next.text : echo.acknowledged === next.text;
          if (guestHasText) typingRef.current?.commit(TEXT_EDITOR_TYPING_HOST_SIGNALS.caretMove);
          if (!guestHasText && !readOnlyRef.current) {
            const before = echo.pending.at(-1) ?? echo.acknowledged ?? next.text;
            echoStateRef.current = { ...echoStateRef.current, pending: [...echoStateRef.current.pending, next.text].slice(-TEXT_EDITOR_PENDING_EDIT_LIMIT) };
            const reason = refusalReason(await onAction({ controllerId, action: textEditorActions.edit, args: { surfaceId, text: next.text, [TEXT_EDITOR_TYPING_BUFFER_ARG]: surfaceId } }));
            if (reason === null) {
              typingRef.current?.typed(textEditorActions.edit, before);
              publishTypingPreview(surfaceId, next.text);
            }
            if (reason !== null) {
              if (TEXT_EDITOR_READ_ONLY_REFUSALS.has(reason)) {
                readOnlyRef.current = true;
                setReadOnly(true);
              }
              const refused = refuseTextEditorEditV1(echoStateRef.current, next.text);
              echoStateRef.current = { pending: refused.pending, acknowledged: refused.acknowledged };
              if (refused.resync) syncSessionRef.current(true);
              return;
            }
          }
          if (selectionUndeclaredRef.current) return;
          const reason = refusalReason(await onAction({ controllerId, action: textEditorActions.select, args: { surfaceId, start: next.start, end: next.end } }));
          if (reason === "undeclared-action") selectionUndeclaredRef.current = true;
        },
        (a, b) => a.text === b.text && a.start === b.start && a.end === b.end,
      ),
    [],
  );
  const moveExplicitHistory = useCallback((direction: "undo" | "redo") => {
    if (!explicitDraft) return false;
    const history = explicitHistoryRef.current;
    const source = direction === "undo" ? history.past : history.future;
    const next = source.at(-1);
    if (next === undefined) return true;
    explicitHistoryRef.current = direction === "undo"
      ? { past: history.past.slice(0, -1), current: next, future: [...history.future, history.current] }
      : { past: [...history.past, history.current], current: next, future: history.future.slice(0, -1) };
    const session = sessionRef.current;
    session?.setText(next);
    session?.setSelectionRange(next.length, next.length);
    echoStateRef.current = { pending: [], acknowledged: next };
    onDraftChange?.(next);
    return true;
  }, [explicitDraft, onDraftChange]);

  const syncSession = useCallback(
    (resync = false) => {
      if (renameActiveRef.current) return;
      if (spliceTypingRef.current) {
        const session = sessionRef.current;
        let show: TextEditorSpliceViewV1 = null;
        if (resync || spliceHostRef.current === null) {
          spliceHostRef.current = textEditorSpliceHostV1(scene.buffer, textEditorAppliedSpliceV1(scene.selectionJson));
          reconciledRef.current = { scene, pack: textEditorSyncPackV1(scene, true) };
        } else if (reconciledRef.current?.scene !== scene) {
          const local = session?.text() ?? scene.buffer;
          const received = receiveTextEditorSceneV1(spliceHostRef.current, scene.buffer, textEditorAppliedSpliceV1(scene.selectionJson), local, textEditorSessionSelectionV1(session, local));
          spliceHostRef.current = received.host;
          reconciledRef.current = { scene, pack: textEditorSyncPackV1(scene, false) };
          show = received.show;
        }
        const pack = reconciledRef.current.pack;
        if (session === null) return;
        if (resync || syncedRef.current?.session !== session || !sameScenePackV1(syncedRef.current.pack, pack)) {
          syncedRef.current = { session, pack };
          try {
            session.syncFromScenePack?.(pack);
          } catch {
            return;
          }
        }
        showTextEditorSpliceViewV1(session, show);
        return;
      }
      if (resync) {
        echoStateRef.current = { pending: [], acknowledged: scene.buffer };
        reconciledRef.current = { scene, pack: textEditorSyncPackV1(scene, true) };
      } else if (reconciledRef.current?.scene !== scene) {
        const echo = reconcileTextEditorEchoV1(echoStateRef.current, scene.buffer);
        echoStateRef.current = { pending: echo.pending, acknowledged: echo.acknowledged };
        reconciledRef.current = { scene, pack: textEditorSyncPackV1(scene, echo.external) };
      }
      const session = sessionRef.current;
      const pack = reconciledRef.current.pack;
      if (session === null) return;
      if (!resync && syncedRef.current?.session === session && sameScenePackV1(syncedRef.current.pack, pack)) return;
      syncedRef.current = { session, pack };
      try {
        session.syncFromScenePack?.(pack);
      } catch (error) {
      }
    },
    [scene],
  );
  syncSessionRef.current = syncSession;

  const [sessionEpoch, setSessionEpoch] = useState(0);

  useEffect(() => {
    syncSession();
    // sessionEpoch: re-sync immediately after GraphWasmCanvas (re)attaches a session (e.g. the stub -> real wasm swap),
    // since the attach lifecycle is independent of scene changes and a ref update alone would not otherwise re-trigger this effect.
  }, [syncSession, sessionEpoch]);

  const wasmEditorSurfaceShellScope = useShellScopeOptional();
  useCanvasAppearanceSync(
    () => {
      syncSessionCanvasTheme(sessionRef.current);
    },
    true,
    wasmEditorSurfaceShellScope?.rootRef.current ?? undefined,
  );

  const presenceWindowId = surfaceId || "text";
  const surfaceRef = useRef<HTMLDivElement>(null);
  const [presenceFrame, setPresenceFrame] = useState(0);
  /** ✏️ Publishes this text window's caret in the editor's WORLD coordinates (plus its camera and size) for the next
   * presence beat, so every peer paints it at the same text position through its own camera. */
  const publishCaretPresence = useCallback(() => {
    const session = sessionRef.current;
    if (!session) return;
    try {
      const world = JSON.parse(session.caretWorldJson()) as { readonly x?: number; readonly y?: number } | null;
      const camera = JSON.parse(session.cameraJson()) as { readonly x?: number; readonly y?: number; readonly zoom?: number };
      const rect = surfaceRef.current?.getBoundingClientRect();
      publishLocalPresenceWindowViewV1("local", presenceWindowId, {
        windowId: presenceWindowId,
        space: "text",
        kind: { kind: "canvas", x: camera.x ?? 0, y: camera.y ?? 0, zoom: camera.zoom ?? 1 },
        size: [rect?.width ?? 0, rect?.height ?? 0],
        ...(world?.x == null || world?.y == null ? {} : { pointer: [world.x, world.y, 0] as const }),
      });
      publishLocalActiveToolV1("local", "edit");
    } catch {
      return;
    }
  }, [presenceWindowId]);
  useEffect(() => () => clearLocalPresenceWindowViewV1(presenceWindowId), [presenceWindowId]);
  const projectPeerCaret = useCallback((world: readonly [number, number]): { readonly x: number; readonly y: number } | null => {
    const session = sessionRef.current;
    if (!session) return null;
    try {
      const screen = JSON.parse(session.worldToScreenJson(world[0], world[1])) as { readonly x?: number; readonly y?: number } | null;
      return screen?.x == null || screen?.y == null ? null : { x: screen.x, y: screen.y };
    } catch {
      return null;
    }
  }, []);

  const emitSelection = useCallback(() => {
    deliver();
    publishCaretPresence();
  }, [deliver, publishCaretPresence]);

  const sinkRef = useRef<HTMLTextAreaElement>(null);
  const caretCadenceRef = useRef<TextEditorCaretCadenceV1 | null>(null);
  useEffect(() => {
    const sink = sinkRef.current;
    if (!sink) return;
    const cadence = installTextEditorCaretCadenceV1(sink, (visible) => {
      const session = sessionRef.current;
      if (!session) return;
      session.setCaretVisible(visible);
    });
    caretCadenceRef.current = cadence;
    return () => {
      cadence.dispose();
      if (caretCadenceRef.current === cadence) caretCadenceRef.current = null;
    };
  }, []);
  /** ⌨️ The typing run ends as ONE edit when the editor loses focus or the page is hidden or left (a run pending for less than the
   * idle bound is never lost to a closed tab), and when the editor unmounts. */
  useEffect(() => {
    const sink = sinkRef.current;
    if (!sink) return;
    const document = sink.ownerDocument;
    const blur = () => typingRef.current?.commit(TEXT_EDITOR_TYPING_HOST_SIGNALS.blur);
    const hidden = () => typingRef.current?.commit(TEXT_EDITOR_TYPING_HOST_SIGNALS.hidden);
    const visibility = () => {
      if (document.visibilityState === "hidden") hidden();
    };
    sink.addEventListener("blur", blur);
    document.defaultView?.addEventListener("pagehide", hidden);
    document.addEventListener("visibilitychange", visibility);
    return () => {
      sink.removeEventListener("blur", blur);
      document.defaultView?.removeEventListener("pagehide", hidden);
      document.removeEventListener("visibilitychange", visibility);
      typingRef.current?.dispose();
    };
  }, []);
  useEffect(() => {
    const sink = sinkRef.current;
    if (!sink) return;
    const onBeforeInput = (event: InputEvent) => {
      if (event.inputType !== "insertText" && event.inputType !== "insertFromDrop") return;
      const data = event.data ?? event.dataTransfer?.getData("text/plain") ?? "";
      event.preventDefault();
      const session = sessionRef.current;
      if (!session || readOnlyRef.current || data.length === 0) return;
      session.insertText(data);
      emitSelection();
    };
    sink.addEventListener("beforeinput", onBeforeInput);
    return () => sink.removeEventListener("beforeinput", onBeforeInput);
  }, [emitSelection]);

  const [wasmSession, setWasmSession] = useState<FrameworkEditorSession | null>(null);
  const [renameDraft, setRenameDraft] = useState<RenameDraft | null>(null);
  const [renamePosition, setRenamePosition] = useState<{ readonly x: number; readonly y: number } | null>(null);
  const [completionsOpen, setCompletionsOpen] = useState(false);
  const [completionIndex, setCompletionIndex] = useState(0);
  const [contextMenu, setContextMenu] = useState<(SurfaceContextMenuResult & { readonly position: { readonly x: number; readonly y: number } }) | null>(null);
  const contextMenuTitleLabel = useLabel(contextMenu?.titleKey ?? "ui.surfaceContextMenu.editor");
  const editorLabel = useLabel(scene.language ? "ui.host.languageDocument" : "ui.host.documentPlaceholder", { language: scene.language });

  const completions = useMemo(() => parseJsonOr<readonly CompletionItem[]>(scene.completionsJson, []), [scene.completionsJson]);
  const renameInfo = useMemo(() => parseJsonOr<RenameInfo | null>(scene.renameJson, null), [scene.renameJson]);
  const newlineGates = useMemo(() => (scene.newlineGatesJson ? new Set(parseJsonOr<readonly number[]>(scene.newlineGatesJson, [])) : null), [scene.newlineGatesJson]);

  useEffect(() => {
    if (completions.length === 0 && completionsOpen) setCompletionsOpen(false);
    if (completionIndex >= completions.length) setCompletionIndex(0);
  }, [completions, completionsOpen, completionIndex]);

  useEffect(() => {
    let cancelled = false;
    void createEditorSession().then((session) => {
      if (!cancelled) setWasmSession(session);
    });
    return () => {
      cancelled = true;
    };
  }, []);

  const sessionFactory = useCallback(() => {
    // Empty pkg stub (`export class EditorSession {}`) must not replace the no-op host fallback.
    if (wasmSession && typeof wasmSession.attachCanvas === "function") return wasmSession;
    return {
      attachCanvas: async () => undefined,
      setSize: () => {},
      renderFrame: () => {},
      syncFromSceneJson: () => {},
      syncFromScenePack: () => {},
      setText: () => {},
      text: () => scene.buffer,
      caret: () => scene.buffer.length,
      anchor: () => 0,
      pointerDownScreen: () => {},
      pointerMoveScreen: () => {},
      pointerUpScreen: () => {},
      pointerCancelScreen: () => {},
      wheelScrollScreen: () => {},
      insertText: () => {},
      backspace: () => {},
      deleteForward: () => {},
      selectAll: () => {},
      replaceSelection: () => {},
      selectionText: () => "",
      hoverTokenRangeJson: () => "null",
      setHoverRange: () => {},
      cameraJson: () => "{}",
      setCanvasThemeJson: () => {},
      moveLeft: () => {},
      moveRight: () => {},
      moveUp: () => {},
      moveDown: () => {},
      moveLineStart: () => {},
      moveLineEnd: () => {},
      tabInsertText: () => "  ",
      setSelectionRange: () => {},
      selectSpanAt: () => {},
      selectSpanAtScreen: () => {},
      pickTargetsAtScreenJson: () => "[]",
      caretWorldJson: () => "null",
      worldToScreenJson: () => "null",
      setSelectionOccurrencesJson: () => {},
      setExtraCaretsJson: () => {},
      setCaretVisible: () => {},
    } satisfies FrameworkEditorSession;
    // Deliberately omits scene.buffer: GraphWasmCanvas re-attaches the GPU canvas whenever sessionFactory's
    // identity changes, so this must stay stable across content edits — only the wasmSession load transition matters.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [wasmSession]);

  const caretScreenPosition = useCallback((session: FrameworkEditorSession): { readonly x: number; readonly y: number } | null => {
    try {
      const world = JSON.parse(session.caretWorldJson()) as { readonly x?: number; readonly y?: number } | null;
      if (world?.x == null || world?.y == null) return null;
      const screen = JSON.parse(session.worldToScreenJson(world.x, world.y)) as { readonly x?: number; readonly y?: number } | null;
      if (screen?.x == null || screen?.y == null) return null;
      return { x: screen.x, y: screen.y };
    } catch {
      return null;
    }
  }, []);

  const openCompletions = useCallback(() => {
    if (completions.length === 0) return;
    setCompletionsOpen(true);
    setCompletionIndex(0);
  }, [completions.length]);

  const applyCompletion = useCallback(
    (item: CompletionItem) => {
      const session = sessionRef.current;
      if (!session) return;
      const text = session.text();
      const caret = session.caret();
      const prefixStart = identifierPrefixStart(text, caret);
      session.setSelectionRange(prefixStart, caret);
      session.replaceSelection(item.insertText ?? item.label);
      emitSelection();
      setCompletionsOpen(false);
    },
    [emitSelection],
  );

  const startRename = useCallback(() => {
    const session = sessionRef.current;
    if (!session || !renameInfo) return;
    renameActiveRef.current = true;
    setRenameDraft({ occurrences: renameInfo.occurrences, text: renameInfo.name });
    setRenamePosition(caretScreenPosition(session));
  }, [renameInfo, caretScreenPosition]);

  const updateRenamePreview = useCallback(
    (nextText: string) => {
      const session = sessionRef.current;
      if (!session || !renameDraft) return;
      const preview = multiSpanReplace(scene.buffer, renameDraft.occurrences, nextText);
      session.setText(preview.text);
      session.setSelectionOccurrencesJson(JSON.stringify(preview.occurrences));
      session.setExtraCaretsJson(JSON.stringify(preview.occurrences.map((occ) => occ.start)));
      setRenameDraft({ ...renameDraft, text: nextText });
    },
    [renameDraft, scene.buffer],
  );

  const commitRename = useCallback(() => {
    if (!renameDraft) return;
    dispatch(textEditorActions.commitRename, { occurrences: renameDraft.occurrences, text: renameDraft.text });
    renameActiveRef.current = false;
    setRenameDraft(null);
    setRenamePosition(null);
  }, [dispatch, renameDraft]);

  const cancelRename = useCallback(() => {
    const session = sessionRef.current;
    if (session) {
      session.setText(scene.buffer);
    }
    renameActiveRef.current = false;
    setRenameDraft(null);
    setRenamePosition(null);
  }, [scene.buffer]);

  const dismissContextMenu = useCallback(() => setContextMenu(null), []);

  // Stable identity: GraphWasmCanvas re-attaches the GPU canvas whenever this prop's identity changes,
  // so it must not close over anything that changes per scene update (see sessionEpoch above for re-sync).
  const onSessionReady = useCallback((session: GraphWasmSession) => {
    sessionRef.current = session as FrameworkEditorSession;
    sessionRef.current.setCaretVisible(caretCadenceRef.current?.visible() ?? false);
    syncSessionCanvasTheme(sessionRef.current);
    setSessionEpoch((epoch) => epoch + 1);
  }, []);

  return (
    <div ref={surfaceRef} className="relative min-h-0 flex-1">
      <GraphWasmCanvas className="absolute inset-0" sessionFactory={sessionFactory} onSessionReady={onSessionReady} enablePointer={false} />
      <TextPeerCaretsOverlayV1 windowId={presenceWindowId} project={projectPeerCaret} frame={presenceFrame + sessionEpoch} lineHeightPx={16} locale={typeof document !== "undefined" ? document.documentElement.lang : undefined} />
      <div
        className="absolute inset-0"
        onPointerDown={(event) => {
          const session = sessionRef.current;
          if (!session) return;
          const rect = event.currentTarget.getBoundingClientRect();
          const sx = event.clientX - rect.left;
          const sy = event.clientY - rect.top;
          if (event.detail >= 2) {
            session.selectSpanAtScreen(sx, sy);
            emitSelection();
            return;
          }
          session.pointerDownScreen(sx, sy, event.button);
          emitSelection();
        }}
        onPointerMove={(event) => {
          const session = sessionRef.current;
          if (!session) return;
          const rect = event.currentTarget.getBoundingClientRect();
          session.pointerMoveScreen(event.clientX - rect.left, event.clientY - rect.top, event.buttons);
          try {
            const hover = JSON.parse(session.hoverTokenRangeJson()) as SpanRange | null;
            const changed = (hover?.start ?? null) !== (lastHoverRangeRef.current?.start ?? null) || (hover?.end ?? null) !== (lastHoverRangeRef.current?.end ?? null);
            if (changed) {
              lastHoverRangeRef.current = hover;
              if (hover) {
                session.setHoverRange(hover.start, hover.end);
                dispatch(textEditorActions.hover, { start: hover.start, end: hover.end });
              }
            }
          } catch {
            /* hover range unavailable */
          }
        }}
        onPointerUp={(event) => {
          const session = sessionRef.current;
          if (!session) return;
          const rect = event.currentTarget.getBoundingClientRect();
          session.pointerUpScreen(event.clientX - rect.left, event.clientY - rect.top, event.buttons);
          emitSelection();
        }}
        onPointerCancel={() => {
          const session = sessionRef.current;
          if (!session) return;
          session.pointerCancelScreen();
        }}
        onWheel={(event) => {
          const session = sessionRef.current;
          if (!session) return;
          event.preventDefault();
          session.wheelScrollScreen(event.deltaY);
          dispatch("setCamera", { camera: JSON.parse(session.cameraJson()) });
          publishCaretPresence();
          setPresenceFrame((frame) => frame + 1);
        }}
        onContextMenu={(event) => {
          event.preventDefault();
          event.stopPropagation();
          void (async () => {
          const session = sessionRef.current;
          if (!session) return;
          dismissContextMenu();
          const rect = event.currentTarget.getBoundingClientRect();
          const sx = event.clientX - rect.left;
          const sy = event.clientY - rect.top;
          session.pointerDownScreen(sx, sy, 0);
          session.pointerUpScreen(sx, sy, 0);
          emitSelection();
          if (event.altKey && completions.length > 0) {
            openCompletions();
            return;
          }
          const pickTargets = parseJsonOr<readonly PickTarget[]>(session.pickTargetsAtScreenJson(sx, sy), []);
          const hasSelection = session.anchor() !== session.caret();
          const localActions: Record<string, () => void> = {
            requestCompletions: openCompletions,
            selectToken: () => {
              session.selectSpanAt(session.caret());
              emitSelection();
            },
            selectLine: () => {
              const caret = session.caret();
              const buffer = scene.buffer;
              const lines = buffer.split("\n");
              let offset = 0;
              let lineIndex = 0;
              for (let i = 0; i < lines.length; i++) {
                const next = offset + (lines[i]?.length ?? 0) + 1;
                if (caret < next || i === lines.length - 1) {
                  lineIndex = i;
                  break;
                }
                offset = next;
              }
              offset = 0;
              for (let i = 0; i < lineIndex; i++) offset += (lines[i]?.length ?? 0) + 1;
              const lineLength = lines[lineIndex]?.length ?? 0;
              session.setSelectionRange(offset, offset + lineLength);
              emitSelection();
            },
            selectAll: () => {
              session.setSelectionRange(0, scene.buffer.length);
              emitSelection();
            },
            commitRename: () => {
              if (renameInfo) startRename();
            },
            cut: () => {
              document.execCommand("cut");
            },
            copy: () => {
              document.execCommand("copy");
            },
            paste: () => {
              document.execCommand("paste");
            },
            formatDocument: () => dispatch(textEditorActions.formatDocument ?? "formatDocument"),
            lintDocument: () => dispatch("lintDocument"),
          };
          for (const target of pickTargets) {
            localActions[`pick:${target.domain}:${target.id}`] = () => {
              /* pick handled via menu row args if present */
            };
          }
          const dispatchTextEditorMenu = (action: string, args?: Record<string, unknown>) => {
            if (localActions[action]) {
              localActions[action]!();
              return;
            }
            dispatch(action, args);
          };
          const menu = await openSurfaceContextMenu(
            requestContextMenu,
            {
              menu: { id: "textEditor", args: null },
              surface: {
                surfaceId,
